<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>'Notifications','subtitle'=>'Request updates and operational alerts assigned to your account.']) ?><section class="panel"><div class="panel-head"><div><h2>Notification Center</h2><p><?= count($notifications) ?> recent notification(s)</p></div><form method="post" action="<?= site_url('notifications/read-all') ?>"><?= csrf_field() ?><button class="btn" type="submit">Mark all read</button></form></div><div class="notification-list"><?php foreach($notifications as $n): ?><article class="notification-row <?= $n['is_read']?'':'unread' ?>"><span class="activity-icon"><?= ui_icon('bell') ?></span><div><b><?= esc(status_label($n['type'])) ?></b><p><?= esc($n['message']) ?></p><small><?= esc(fmt_date($n['created_at'],true)) ?></small></div><?php if(!$n['is_read']): ?><form method="post" action="<?= site_url('notifications/'.$n['id'].'/read') ?>"><?= csrf_field() ?><button class="btn small" type="submit">Mark read</button></form><?php endif; ?></article><?php endforeach; ?><?php if(empty($notifications)): ?><div class="empty">You have no notifications.</div><?php endif; ?></div></section><?= $this->endSection() ?>
